<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#f4f0e7">
<title>Dune Line — Take the long way to the lights</title>
<style>
  :root {
    --paper: #f4f0e7;
    --paper-deep: #eae3d5;
    --ink: #25242b;
    --muted: #706c69;
    --night: #20232b;
    --night-soft: #30333b;
    --orange: #d75d3b;
    --yellow: #e6cf87;
    --line: #d4cec2;
    --serif: Georgia, "Times New Roman", serif;
    --sans: "Helvetica Neue", Helvetica, Arial, sans-serif;
    --wrap: 1160px;
  }

  * { box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    margin: 0;
    color: var(--ink);
    background: var(--paper);
    font-family: var(--sans);
    -webkit-font-smoothing: antialiased;
  }
  a { color: inherit; text-decoration: none; }
  button, input, select { font: inherit; }
  button, a { -webkit-tap-highlight-color: transparent; }
  button { cursor: pointer; }
  :focus-visible { outline: 3px solid #dc754e; outline-offset: 4px; }
  svg { display: block; }
  .wrap { width: min(var(--wrap), calc(100% - 64px)); margin-inline: auto; }
  .eyebrow {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: .16em;
    line-height: 1.4;
    text-transform: uppercase;
  }
  .eyebrow::before {
    content: "";
    width: 25px;
    height: 1px;
    background: currentColor;
  }
  .serif { font-family: var(--serif); font-weight: 400; }
  .button {
    min-height: 52px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 30px;
    padding: 0 20px;
    border: 1px solid var(--ink);
    background: var(--ink);
    color: #fffdf7;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: .01em;
    transition: background .2s, color .2s, transform .2s;
  }
  .button:hover { background: var(--orange); border-color: var(--orange); transform: translateY(-2px); }
  .button .arrow { font-size: 17px; font-weight: 400; line-height: 1; }
  .text-link {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    font-size: 12px;
    font-weight: 700;
    border-bottom: 1px solid currentColor;
    padding: 8px 0;
  }
  .text-link span { font-size: 17px; font-weight: 400; }

  /* Header */
  .announcement {
    min-height: 30px;
    padding: 8px 20px;
    color: #e8e2d5;
    background: var(--night);
    text-align: center;
    font-size: 9px;
    font-weight: 700;
    letter-spacing: .14em;
    text-transform: uppercase;
  }
  .announcement b { color: #e6a77d; margin: 0 9px; }
  .nav {
    height: 79px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 30px;
    border-bottom: 1px solid var(--line);
  }
  .brand { display: inline-flex; align-items: center; gap: 10px; flex-shrink: 0; }
  .brand-mark {
    width: 36px;
    height: 36px;
    display: grid;
    place-items: center;
    border: 1px solid currentColor;
    border-radius: 50%;
  }
  .brand-name { font-size: 16px; font-weight: 800; letter-spacing: -.06em; }
  .nav-links { display: flex; align-items: center; gap: 34px; }
  .nav-links a { font-size: 12px; font-weight: 600; }
  .nav-links a:hover, .footer-links a:hover { color: var(--orange); }
  .nav-cta { min-height: 42px; padding: 0 17px; gap: 22px; }
  .mobile-nav { display: none; }

  /* Hero */
  .hero {
    display: grid;
    grid-template-columns: .95fr 1.05fr;
    gap: 56px;
    align-items: center;
    padding-top: 55px;
    padding-bottom: 58px;
  }
  .hero-copy { padding: 15px 0 4px; }
  .hero .eyebrow { color: #a14d35; }
  h1 {
    margin: 25px 0 23px;
    font-family: var(--serif);
    font-size: clamp(58px, 6.2vw, 82px);
    font-weight: 400;
    letter-spacing: -.065em;
    line-height: .99;
  }
  h1 em { color: var(--orange); font-weight: 400; }
  .hero-description {
    max-width: 405px;
    color: #68635f;
    font-size: 15px;
    line-height: 1.8;
  }
  .hero-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 28px; margin-top: 30px; }
  .hero-note {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-top: 59px;
    color: #77716a;
    font-size: 10px;
    line-height: 1.5;
  }
  .hero-note .sun-icon { color: var(--orange); flex: 0 0 auto; }
  .hero-note strong { display: block; color: var(--ink); font-size: 11px; }

  .poster {
    position: relative;
    overflow: hidden;
    background: #292b39;
    aspect-ratio: 1 / 1.03;
  }
  .poster > svg { width: 100%; height: 100%; object-fit: cover; }
  .poster-top {
    position: absolute;
    top: 23px;
    left: 25px;
    right: 25px;
    display: flex;
    justify-content: space-between;
    color: #eee6d9;
    font-size: 9px;
    font-weight: 700;
    letter-spacing: .14em;
    text-transform: uppercase;
  }
  .poster-top span:last-child { color: #e1b29b; }
  .poster-bottom {
    position: absolute;
    bottom: 24px;
    left: 25px;
    right: 25px;
    display: flex;
    align-items: end;
    justify-content: space-between;
    color: #f7e9d8;
  }
  .poster-bottom small { display: block; margin-bottom: 5px; font-size: 9px; letter-spacing: .14em; text-transform: uppercase; }
  .poster-bottom strong { font-family: var(--serif); font-size: 25px; font-weight: 400; }
  .poster-stamp {
    width: 57px;
    height: 57px;
    display: grid;
    place-items: center;
    border: 1px solid rgba(255, 244, 224, .6);
    border-radius: 50%;
    text-align: center;
    font-size: 8px;
    line-height: 1.5;
    letter-spacing: .12em;
  }

  /* Route strip */
  .route-strip { border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
  .route-inner {
    min-height: 95px;
    display: grid;
    grid-template-columns: 1.1fr 1fr 1fr 1fr;
    align-items: center;
  }
  .route-heading { display: flex; align-items: center; gap: 12px; font-size: 11px; font-weight: 700; }
  .route-heading svg { color: var(--orange); }
  .route-stat { padding-left: 30px; border-left: 1px solid var(--line); }
  .route-stat small { display: block; margin-bottom: 6px; color: #8a8279; font-size: 9px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
  .route-stat span { font-family: var(--serif); font-size: 17px; }

  /* Features */
  .section { padding: 105px 0; }
  .section-head { display: flex; align-items: end; justify-content: space-between; gap: 30px; margin-bottom: 48px; }
  .section-head h2, .schedule-intro h2, .pricing-intro h2 {
    margin: 16px 0 0;
    font-family: var(--serif);
    font-size: clamp(39px, 4.2vw, 54px);
    font-weight: 400;
    line-height: 1.07;
    letter-spacing: -.045em;
  }
  .section-head > p {
    max-width: 310px;
    margin: 0 0 4px;
    color: var(--muted);
    font-size: 13px;
    line-height: 1.8;
  }
  .features { display: grid; grid-template-columns: repeat(3, 1fr); border-top: 1px solid var(--line); }
  .feature { padding: 27px 32px 0 0; }
  .feature + .feature { border-left: 1px solid var(--line); padding-left: 32px; }
  .feature-top { display: flex; align-items: start; justify-content: space-between; min-height: 112px; }
  .feature-number { color: #aaa094; font-size: 10px; letter-spacing: .12em; }
  .feature-icon { color: #a9543a; }
  .feature h3 { margin: 0 0 13px; font-family: var(--serif); font-size: 25px; font-weight: 400; letter-spacing: -.025em; }
  .feature p { max-width: 290px; margin: 0; color: var(--muted); font-size: 13px; line-height: 1.8; }

  /* Timetable */
  .schedule { padding: 91px 0 94px; background: var(--night); color: #f3eee4; }
  .schedule-layout { display: grid; grid-template-columns: .8fr 1.2fr; gap: 95px; }
  .schedule .eyebrow { color: #e5a17d; }
  .schedule-intro p { max-width: 300px; margin: 22px 0 28px; color: #b0ada9; font-size: 13px; line-height: 1.8; }
  .schedule-intro .text-link { color: #e9d4ae; }
  .schedule-card { min-width: 0; }
  .table-heading { display: flex; justify-content: space-between; align-items: baseline; gap: 15px; margin-bottom: 20px; }
  .table-heading strong { font-size: 12px; }
  .table-heading span { color: #a9a5a1; font-size: 10px; letter-spacing: .06em; }
  .table-scroll { overflow-x: auto; }
  table { width: 100%; min-width: 490px; border-collapse: collapse; text-align: left; }
  th { padding: 13px 4px; color: #9b9997; border-bottom: 1px solid #66666a; font-size: 9px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; }
  td { padding: 18px 4px; border-bottom: 1px solid #484a50; font-size: 12px; }
  td:first-child, td:nth-child(2) { font-family: var(--serif); font-size: 21px; }
  td sup { color: #d8a287; font-family: var(--sans); font-size: 9px; vertical-align: super; }
  .daily { display: inline-flex; align-items: center; gap: 7px; color: #cfcbc4; font-size: 11px; }
  .daily::before { content: ""; width: 6px; height: 6px; background: #d4a977; border-radius: 50%; }
  .table-foot { display: flex; justify-content: space-between; gap: 20px; margin-top: 17px; color: #a9a5a1; font-size: 10px; line-height: 1.6; }
  .scroll-hint { display: none; }

  /* Pricing */
  .pricing-intro { display: flex; align-items: end; justify-content: space-between; gap: 30px; margin-bottom: 42px; }
  .pricing-intro > p { max-width: 300px; margin: 0 0 4px; color: var(--muted); font-size: 13px; line-height: 1.8; }
  .price-grid { display: grid; grid-template-columns: repeat(3, 1fr); border: 1px solid var(--line); }
  .price-card { display: flex; flex-direction: column; min-height: 381px; padding: 30px; }
  .price-card + .price-card { border-left: 1px solid var(--line); }
  .price-card.featured { background: #e8dfcf; }
  .price-top { display: flex; justify-content: space-between; align-items: center; gap: 10px; min-height: 22px; }
  .price-top > span:first-child { font-size: 10px; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; }
  .popular { padding: 6px 8px; background: #d85f3c; color: white; font-size: 8px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
  .price-card h3 { margin: 24px 0 7px; font-family: var(--serif); font-size: 28px; font-weight: 400; letter-spacing: -.03em; }
  .price-description { min-height: 42px; margin: 0; color: var(--muted); font-size: 12px; line-height: 1.7; }
  .price { margin: 27px 0 22px; font-family: var(--serif); font-size: 39px; line-height: 1; letter-spacing: -.04em; }
  .price small { margin-left: 3px; color: var(--muted); font-family: var(--sans); font-size: 10px; letter-spacing: 0; }
  .price-card .button { width: 100%; justify-content: space-between; margin-top: auto; }
  .price-card:not(.featured) .button { background: transparent; color: var(--ink); }
  .price-card:not(.featured) .button:hover { background: var(--ink); color: white; border-color: var(--ink); }
  .price-footnote { margin: 17px 0 0; color: #888078; font-size: 10px; line-height: 1.6; }

  /* Testimonial */
  .quote-section { padding-bottom: 105px; }
  .quote-box {
    position: relative;
    overflow: hidden;
    display: grid;
    grid-template-columns: .8fr 1.2fr;
    align-items: center;
    min-height: 290px;
    padding: 55px 65px;
    background: #e9d4c3;
  }
  .quote-art { position: absolute; left: -35px; bottom: -105px; width: 320px; height: 250px; opacity: .65; }
  .quote-label { align-self: start; position: relative; z-index: 1; }
  .quote-content { position: relative; z-index: 1; }
  .stars { margin-bottom: 16px; color: #b34e32; font-size: 12px; letter-spacing: .18em; }
  blockquote { margin: 0; max-width: 630px; font-family: var(--serif); font-size: clamp(25px, 2.8vw, 36px); font-weight: 400; line-height: 1.26; letter-spacing: -.025em; }
  .quote-credit { margin: 22px 0 0; font-size: 11px; font-weight: 700; }
  .quote-credit span { margin-left: 9px; color: #826d62; font-weight: 400; }

  /* Footer */
  footer { background: var(--night); color: #f4eee4; }
  .footer-main { display: flex; justify-content: space-between; gap: 40px; padding: 55px 0 50px; }
  .footer-copy { max-width: 270px; margin: 17px 0 0; color: #aaa7a2; font-size: 12px; line-height: 1.8; }
  .footer-links { display: flex; flex-wrap: wrap; align-content: start; gap: 28px; padding-top: 10px; }
  .footer-links a { font-size: 11px; font-weight: 600; }
  .footer-bottom { display: flex; justify-content: space-between; gap: 20px; padding: 19px 0; border-top: 1px solid #46484d; color: #9d9c99; font-size: 10px; line-height: 1.5; }
  .footer-bottom span:last-child { letter-spacing: .09em; text-transform: uppercase; }

  /* Fare dialog */
  dialog {
    width: min(440px, calc(100% - 36px));
    max-height: calc(100% - 36px);
    padding: 0;
    border: 0;
    color: var(--ink);
    background: var(--paper);
    box-shadow: 0 25px 90px rgba(0,0,0,.3);
  }
  dialog::backdrop { background: rgba(20, 21, 27, .72); }
  .dialog-inner { padding: 32px; }
  .dialog-top { display: flex; align-items: center; justify-content: space-between; }
  .close-dialog { width: 36px; height: 36px; border: 1px solid var(--line); background: transparent; font-size: 21px; }
  dialog h2 { margin: 25px 0 10px; font-family: var(--serif); font-size: 38px; font-weight: 400; letter-spacing: -.04em; }
  dialog p { color: var(--muted); font-size: 13px; line-height: 1.7; }
  .field { display: block; margin-top: 20px; font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
  .field select, .field input {
    width: 100%;
    min-height: 48px;
    margin-top: 8px;
    padding: 10px 12px;
    border: 1px solid #c7bfb2;
    border-radius: 0;
    background: #fbf8f1;
    color: var(--ink);
    font-size: 13px;
    letter-spacing: 0;
    text-transform: none;
  }
  .dialog-submit { width: 100%; margin-top: 24px; justify-content: space-between; }
  .dialog-result { margin: 17px 0 0; padding: 12px; background: #e7dfd1; color: var(--ink); }

  @media (max-width: 900px) {
    .wrap { width: min(100% - 48px, var(--wrap)); }
    .nav-links { gap: 20px; }
    .hero { gap: 30px; }
    h1 { font-size: clamp(53px, 7vw, 68px); }
    .hero-note { margin-top: 35px; }
    .schedule-layout { gap: 45px; }
    .price-card { padding: 25px; }
  }
  @media (max-width: 700px) {
    .wrap { width: calc(100% - 36px); }
    .announcement { font-size: 8px; }
    .nav { height: 68px; }
    .nav-links, .nav > .nav-cta { display: none; }
    .mobile-nav { display: block; position: relative; }
    .mobile-nav summary { list-style: none; cursor: pointer; padding: 10px; font-size: 11px; font-weight: 700; }
    .mobile-nav summary::-webkit-details-marker { display: none; }
    .mobile-nav summary::after { content: " +"; font-size: 17px; }
    .mobile-nav[open] summary::after { content: " −"; }
    .mobile-menu {
      position: absolute;
      z-index: 5;
      top: 44px;
      right: 0;
      width: 205px;
      padding: 10px 18px;
      background: var(--night);
      color: white;
      box-shadow: 0 12px 30px rgba(0,0,0,.15);
    }
    .mobile-menu a { display: block; padding: 13px 0; border-bottom: 1px solid #484a50; font-size: 12px; }
    .mobile-menu a:last-child { border: 0; }
    .hero { grid-template-columns: 1fr; gap: 32px; padding: 47px 0 35px; }
    .hero-copy { padding: 0; }
    h1 { max-width: 550px; font-size: clamp(53px, 11vw, 76px); }
    .hero-description { max-width: 480px; }
    .hero-note { margin-top: 30px; }
    .poster { max-height: 620px; }
    .route-inner { grid-template-columns: repeat(3, 1fr); padding: 20px 0; row-gap: 20px; }
    .route-heading { grid-column: 1 / -1; }
    .route-stat { padding-left: 15px; }
    .route-stat:nth-child(2) { padding-left: 0; border-left: 0; }
    .route-stat span { font-size: 15px; }
    .section { padding: 72px 0; }
    .section-head, .pricing-intro { display: block; margin-bottom: 35px; }
    .section-head > p, .pricing-intro > p { margin-top: 18px; }
    .features { grid-template-columns: 1fr; }
    .feature, .feature + .feature { padding: 25px 0; border-left: 0; border-bottom: 1px solid var(--line); }
    .feature-top { min-height: 78px; }
    .feature p { max-width: 440px; }
    .schedule { padding: 72px 0; }
    .schedule-layout { grid-template-columns: 1fr; gap: 42px; }
    .schedule-intro p { max-width: 430px; }
    .scroll-hint { display: inline; }
    .price-grid { grid-template-columns: 1fr; }
    .price-card { min-height: 320px; }
    .price-card + .price-card { border-left: 0; border-top: 1px solid var(--line); }
    .price-description { min-height: 0; }
    .quote-section { padding-bottom: 72px; }
    .quote-box { grid-template-columns: 1fr; gap: 42px; padding: 36px 28px 45px; }
    .quote-art { left: auto; right: -80px; bottom: -125px; }
    .footer-main { flex-direction: column; }
    .footer-links { gap: 20px; }
    .footer-bottom { flex-direction: column; gap: 7px; }
  }
  @media (prefers-reduced-motion: reduce) {
    html { scroll-behavior: auto; }
    *, *::before, *::after { transition-duration: .01ms !important; }
  }
</style>
</head>
<body>
  <div class="announcement">An overnight journey, a world away <b>✳</b> Dune Junction to Neon City</div>

  <header class="wrap">
    <nav class="nav" aria-label="Main navigation">
      <a class="brand" href="#top" aria-label="Dune Line home">
        <span class="brand-mark" aria-hidden="true">
          <svg width="23" height="20" viewBox="0 0 23 20" fill="none">
            <path d="M2 13.5c3.5-4 6.4-4 9.8-.8 2.6 2.4 5.3 2.4 9.2-1.5M2 16.8c3.5-4 6.4-4 9.8-.8 2.6 2.4 5.3 2.4 9.2-1.5" stroke="currentColor" stroke-width="1.3"/>
            <circle cx="15.5" cy="5.5" r="2.5" fill="currentColor"/>
          </svg>
        </span>
        <span class="brand-name">dune line<span style="color:#d75d3b">.</span></span>
      </a>
      <div class="nav-links">
        <a href="#experience">The experience</a>
        <a href="#timetable">Timetable</a>
        <a href="#fares">Fares</a>
      </div>
      <a class="button nav-cta" href="#fares">Find your seat <span class="arrow">↗</span></a>
      <details class="mobile-nav">
        <summary>Menu</summary>
        <div class="mobile-menu">
          <a href="#experience">The experience</a>
          <a href="#timetable">Timetable</a>
          <a href="#fares">Fares &amp; seats</a>
        </div>
      </details>
    </nav>
  </header>

  <main id="top">
    <section class="hero wrap" aria-labelledby="hero-title">
      <div class="hero-copy">
        <div class="eyebrow">A different way to get there</div>
        <h1 id="hero-title">Take the long way to the <em>lights.</em></h1>
        <p class="hero-description">Leave the ordinary behind. Drift across the desert under a sky full of stars, and wake up somewhere electric.</p>
        <div class="hero-actions">
          <a class="button" href="#fares">Explore the fares <span class="arrow">↗</span></a>
          <a class="text-link" href="#timetable">See the timetable <span>↓</span></a>
        </div>
        <div class="hero-note">
          <svg class="sun-icon" width="29" height="29" viewBox="0 0 29 29" fill="none" aria-hidden="true">
            <circle cx="14.5" cy="14.5" r="5" stroke="currentColor"/>
            <path d="M14.5 1v5M14.5 23v5M1 14.5h5M23 14.5h5M5 5l3.5 3.5M20.5 20.5 24 24M24 5l-3.5 3.5M8.5 20.5 5 24" stroke="currentColor"/>
          </svg>
          <div><strong>Four departures, every evening</strong>One unforgettable night on the rails.</div>
        </div>
      </div>

      <div class="poster" role="img" aria-label="Illustration of a train crossing desert dunes toward a glowing city at night">
        <svg viewBox="0 0 700 720" preserveAspectRatio="xMidYMid slice" aria-hidden="true">
          <defs>
            <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
              <stop stop-color="#242737"/>
              <stop offset=".65" stop-color="#493c4d"/>
              <stop offset="1" stop-color="#a65e52"/>
            </linearGradient>
            <linearGradient id="sun" x1="0" y1="0" x2="0" y2="1">
              <stop stop-color="#f3c095"/>
              <stop offset="1" stop-color="#df8066"/>
            </linearGradient>
            <linearGradient id="dune" x1="0" y1="0" x2="1" y2="1">
              <stop stop-color="#b66e58"/>
              <stop offset="1" stop-color="#714f52"/>
            </linearGradient>
            <radialGradient id="glow">
              <stop stop-color="#f6ac91" stop-opacity=".45"/>
              <stop offset="1" stop-color="#f6ac91" stop-opacity="0"/>
            </radialGradient>
          </defs>
          <rect width="700" height="720" fill="url(#sky)"/>
          <circle cx="513" cy="281" r="191" fill="url(#glow)"/>
          <g fill="#f3d8bf" opacity=".8">
